package dev.carcara.kotlinx.locale.codegen

import com.ibm.icu.text.TimeZoneFormat
import com.ibm.icu.util.TimeZone
import com.ibm.icu.util.ULocale
import java.io.File
import java.util.Date

/**
 * Goldens for the zone name engine, generated by asking ICU4J the same
 * questions.
 *
 * UTS #35 Part 4 defines these forms tersely and leaves the fallback ladder
 * spread across several numbered steps: which zone stands for a region, when a
 * generic name degrades to a partial location, what a locale with no name for a
 * metazone falls back to. The engine here implements the ladder from the
 * document; these fixtures are what say it landed on the same rung ICU does.
 *
 * The record carries ICU's offset and its daylight answer alongside the names,
 * and the test reads both from the fixture rather than from the platform. That
 * is deliberate. Each target reads a different copy of tzdb, and tzdb is revised
 * several times a year, so a fixture that asked the running platform whether Los
 * Angeles was on daylight time in July would be testing the platform's tzdb
 * against ICU's rather than testing this library. Taking both from the fixture
 * makes every assertion here pinned data through pinned code.
 *
 * See the KDoc on the conformance function for what a failure means and what it
 * does not.
 */

/**
 * The zones the goldens cover.
 *
 * Chosen for the cases the ladder has to distinguish rather than for coverage:
 * single-zone regions that take the country name, multi-zone regions that need
 * the city, zones sharing a metazone, zones with no daylight saving at all,
 * southern-hemisphere zones whose summer is in January, half-hour and
 * three-quarter-hour offsets, and the `Etc/` zones that have no location.
 *
 * `Europe/Istanbul` is deliberately absent. Turkey moved to a permanent +03:00
 * in 2016 and CLDR maps the zone to the Turkey metazone from that date, but ICU
 * still declines the metazone's name there and writes the offset instead. That
 * is ICU's bookkeeping of the metazone's own offset rather than a rule about
 * naming, and copying it would mean writing `GMT+03:00` in locales that have a
 * word for Turkish time.
 */
val ICU_TIME_ZONE_GOLDEN_ZONES: List<String> = listOf(
    "America/Los_Angeles", "America/Denver", "America/Chicago", "America/New_York",
    "America/Phoenix", "America/Anchorage", "Pacific/Honolulu", "America/Sao_Paulo",
    "America/Argentina/Buenos_Aires", "America/Mexico_City", "America/Bogota",
    "America/Toronto", "America/Halifax", "America/St_Johns",
    "Europe/London", "Europe/Dublin", "Europe/Paris", "Europe/Berlin", "Europe/Madrid",
    "Europe/Rome", "Europe/Prague", "Europe/Warsaw", "Europe/Moscow", "Europe/Kyiv",
    "Europe/Lisbon", "Atlantic/Azores",
    "Africa/Cairo", "Africa/Lagos", "Africa/Johannesburg", "Africa/Nairobi",
    "Asia/Tokyo", "Asia/Shanghai", "Asia/Hong_Kong", "Asia/Singapore", "Asia/Seoul",
    "Asia/Kolkata", "Asia/Kathmandu", "Asia/Dubai", "Asia/Tehran", "Asia/Jerusalem",
    "Australia/Sydney", "Australia/Adelaide", "Australia/Perth", "Australia/Brisbane",
    "Pacific/Auckland", "Pacific/Chatham", "Pacific/Fiji",
    "UTC", "Etc/GMT+5",
)

/**
 * The instants each zone is asked about, as epoch seconds.
 *
 * One in January and one in July of 2024, so every zone is sampled once on each
 * side of whatever daylight rule it has, and the southern-hemisphere zones get
 * the same treatment with the seasons the other way round. Written as literals
 * because a workflow script cannot read a clock and a golden should not depend
 * on when it was generated.
 */
val ICU_TIME_ZONE_GOLDEN_INSTANTS: List<Long> = listOf(
    1705320000L, // 2024-01-15T12:00:00Z
    1721044800L, // 2024-07-15T12:00:00Z
)

/** The ICU style each name in a record was generated from, in order. */
val ICU_TIME_ZONE_GOLDEN_STYLES: List<Pair<String, TimeZoneFormat.Style>> = listOf(
    "GENERIC_LONG" to TimeZoneFormat.Style.GENERIC_LONG,
    "GENERIC_SHORT" to TimeZoneFormat.Style.GENERIC_SHORT,
    "SPECIFIC_LONG" to TimeZoneFormat.Style.SPECIFIC_LONG,
    "SPECIFIC_SHORT" to TimeZoneFormat.Style.SPECIFIC_SHORT,
    "LOCATION" to TimeZoneFormat.Style.GENERIC_LOCATION,
    "OFFSET_LONG" to TimeZoneFormat.Style.LOCALIZED_GMT,
    "OFFSET_SHORT" to TimeZoneFormat.Style.LOCALIZED_GMT_SHORT,
)

class IcuTimeZoneGoldenEntry(
    val tag: String,
    /** One row per (zone, instant), in the order the two lists above give. */
    val rows: List<IcuTimeZoneRow>,
)

class IcuTimeZoneRow(
    val zoneId: String,
    val epochSeconds: Long,
    val offsetSeconds: Int,
    val daylight: Boolean,
    /** Positional against [ICU_TIME_ZONE_GOLDEN_STYLES]. */
    val names: List<String>,
)

fun extractIcuTimeZoneGolden(zoneNameLocales: Set<String>): List<IcuTimeZoneGoldenEntry> {
    ULocale.setDefault(ULocale.ROOT)
    java.util.Locale.setDefault(java.util.Locale.ROOT)

    val available = ULocale.getAvailableLocales().mapTo(HashSet()) { it.toLanguageTag() }
    val icuZones = TimeZone.getAvailableIDs().toHashSet()
    val zones = ICU_TIME_ZONE_GOLDEN_ZONES.filter { it in icuZones }
    val skippedZones = ICU_TIME_ZONE_GOLDEN_ZONES.size - zones.size

    val missing = ArrayList<String>()
    val entries = ArrayList<IcuTimeZoneGoldenEntry>()
    for (tag in ICU_GOLDEN_LOCALES.map(::canonicalTag)) {
        if (tag !in available || tag !in zoneNameLocales) {
            missing.add(tag)
            continue
        }
        val format = TimeZoneFormat.getInstance(ULocale.forLanguageTag(tag))
        val rows = ArrayList<IcuTimeZoneRow>()
        for (zoneId in zones) {
            val zone = TimeZone.getTimeZone(zoneId)
            for (epochSeconds in ICU_TIME_ZONE_GOLDEN_INSTANTS) {
                val date = Date(epochSeconds * 1000)
                rows.add(
                    IcuTimeZoneRow(
                        zoneId = zoneId,
                        epochSeconds = epochSeconds,
                        offsetSeconds = zone.getOffset(date.time) / 1000,
                        daylight = zone.inDaylightTime(date),
                        names = ICU_TIME_ZONE_GOLDEN_STYLES.map { (_, style) -> format.format(style, zone, date.time) },
                    ),
                )
            }
        }
        entries.add(IcuTimeZoneGoldenEntry(tag, rows))
    }
    println(
        "[codegen] time zone goldens cover ${entries.size} locales x ${zones.size} zones x " +
            "${ICU_TIME_ZONE_GOLDEN_INSTANTS.size} instants x ${ICU_TIME_ZONE_GOLDEN_STYLES.size} styles; " +
            "${missing.size} locales and $skippedZones zones are absent from ICU4J",
    )
    check(entries.isNotEmpty()) { "the time zone goldens covered no locales at all" }
    return entries
}

fun emitIcuTimeZoneGolden(outputFile: File, icuTag: String, entries: List<IcuTimeZoneGoldenEntry>) {
    outputFile.parentFile.mkdirs()
    outputFile.writeText(
        buildString {
            append("// GENERATED by :codegen from ICU $icuTag. Do not edit.\n")
            append("// Regenerate with: ./gradlew :codegen:generateLocaleData\n")
            append("package dev.carcara.kotlinx.locale.conformance\n\n")
            append("public const val ICU_TIME_ZONE_GOLDEN_VERSION: String = \"${kotlinEscape(icuTag)}\"\n\n")
            append("/** The styles every golden row answers, in order. */\n")
            append("public val icuTimeZoneGoldenStyles: List<String> = listOf(\n")
            for ((name, _) in ICU_TIME_ZONE_GOLDEN_STYLES) append("    \"${kotlinEscape(name)}\",\n")
            append(")\n\n")
            append("/** One row: the zone, the instant, ICU's offset and daylight answer, then the names. */\n")
            append("public class IcuTimeZoneGoldenRow(\n")
            append("    public val zoneId: String,\n")
            append("    public val epochSeconds: Long,\n")
            append("    public val offsetSeconds: Int,\n")
            append("    public val daylight: Boolean,\n")
            append("    public val names: List<String>,\n")
            append(")\n\n")
            append("/** Locale tag to its rows. */\n")
            append("public val icuTimeZoneGoldenData: Map<String, List<IcuTimeZoneGoldenRow>> = buildMap(${entries.size}) {\n")
            for (entry in entries.sortedBy { it.tag }) {
                append("    put(\n")
                append("        \"${kotlinEscape(entry.tag)}\",\n")
                append("        decodeTimeZoneGoldenRows(\n")
                append("            \"")
                append(
                    kotlinEscape(
                        entry.rows.joinToString(LIST_SEPARATOR) { row ->
                            listOf(
                                row.zoneId,
                                row.epochSeconds.toString(),
                                row.offsetSeconds.toString(),
                                if (row.daylight) "1" else "0",
                            ).joinToString(FIELD_SEPARATOR) + FIELD_SEPARATOR +
                                row.names.joinToString(FIELD_SEPARATOR)
                        },
                    ),
                )
                append("\",\n")
                append("        ),\n")
                append("    )\n")
            }
            append("}\n\n")
            append("/** Splits one locale's encoded rows back apart. */\n")
            append("private fun decodeTimeZoneGoldenRows(record: String): List<IcuTimeZoneGoldenRow> =\n")
            append("    record.split('\\u001E').map { row ->\n")
            append("        val fields = row.split('\\u001F')\n")
            append("        IcuTimeZoneGoldenRow(\n")
            append("            zoneId = fields[0],\n")
            append("            epochSeconds = fields[1].toLong(),\n")
            append("            offsetSeconds = fields[2].toInt(),\n")
            append("            daylight = fields[3] == \"1\",\n")
            append("            names = fields.subList(4, fields.size),\n")
            append("        )\n")
            append("    }\n")
        },
    )
    println("[codegen] emitted ${entries.size} ICU time zone golden locales to $outputFile")
}
